namespace sv_8dd497ccff9a4861bdce5e0cb993cb61;

public enum Theme
{
    Light,
    Dark,
    System
}

public class ThemeInfo
{
    public Theme Theme { get; set; } = Theme.Light;
    public string AccentColor { get; set; } = "#0d6efd";
}

@* 
    This component consumes the cascading ThemeInfo and displays the current
    theme in the header. It works in the static layout because CascadingValueSource
    crosses render mode boundaries.
*@

<span class="theme-indicator" style="color: @(Theme?.AccentColor ?? "#0d6efd");">
    @GetThemeIcon() @(Theme?.Theme.ToString() ?? "Light")
</span>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private string GetThemeIcon() => Theme?.Theme switch
    {
        Theme.Dark => "🌙",
        Theme.System => "💻",
        _ => "☀️"
    };
}

@rendermode InteractiveServer
@inject CascadingValueSource<ThemeInfo> ThemeSource

<button class="btn btn-sm btn-outline-secondary" @onclick="CycleTheme">
    @GetThemeIcon() Toggle Theme
</button>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private string GetThemeIcon() => Theme?.Theme switch
    {
        Theme.Dark => "🌙",
        Theme.System => "💻",
        _ => "☀️"
    };

    private async Task CycleTheme()
    {
        var next = Theme?.Theme switch
        {
            Theme.Light => Theme.Dark,
            Theme.Dark => Theme.System,
            _ => Theme.Light
        };

        await ThemeSource.NotifyChangedAsync(new ThemeInfo
        {
            Theme = next,
            AccentColor = Theme?.AccentColor ?? "#0d6efd"
        });
    }
}

@page "/settings"
@rendermode InteractiveServer
@inject CascadingValueSource<ThemeInfo> ThemeSource

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card p-4" style="max-width: 500px;">
    <h4>Theme</h4>
    <div class="btn-group mb-3" role="group">
        @foreach (var t in Enum.GetValues<Theme>())
        {
            <button class="btn @(t == currentTheme ? "btn-primary" : "btn-outline-primary")"
                    @onclick="() => SetTheme(t)">
                @t
            </button>
        }
    </div>

    <h4>Accent Color</h4>
    <div class="d-flex align-items-center gap-3 mb-3">
        <input type="color" class="form-control form-control-color"
               value="@currentAccent" @onchange="SetAccentColor" />
        <span style="color: @currentAccent; font-weight: bold;">@currentAccent</span>
    </div>

    <button class="btn btn-success" @onclick="Save">Save Preferences</button>
    @if (saved)
    {
        <span class="text-success ms-2">✓ Saved</span>
    }
</div>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private Theme currentTheme;
    private string currentAccent = "#0d6efd";
    private bool saved;

    protected override void OnParametersSet()
    {
        if (Theme is not null)
        {
            currentTheme = Theme.Theme;
            currentAccent = Theme.AccentColor;
        }
    }

    private void SetTheme(Theme theme)
    {
        currentTheme = theme;
        saved = false;
    }

    private void SetAccentColor(ChangeEventArgs e)
    {
        currentAccent = e.Value?.ToString() ?? "#0d6efd";
        saved = false;
    }

    private async Task Save()
    {
        await ThemeSource.NotifyChangedAsync(new ThemeInfo
        {
            Theme = currentTheme,
            AccentColor = currentAccent
        });
        saved = true;
    }
}

